-- 리눅스 세트 229. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 단원·display_order·아이콘은 통합 시 따로 정한다. docs/specs/spec_linux_process_set.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 229, '프로세스 찾고 멈추기 손에 익히기: ps, pgrep, ss -ltnp, kill, pkill', '서버에서 프로세스를 다루는 일을 순서대로 연습합니다. ps -ef·ps -o·ps --sort 로 목록을 보고, pgrep 으로 PID 를 찾고, ss -ltnp 로 포트를 쥔 프로세스를 확인하고, & 와 $! 로 백그라운드 작업의 PID 를 기록한 뒤, kill·kill -9·pkill 로 종료합니다.', 'linux', '리눅스'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 229);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 229, 1, '실행 중인 프로세스 전체 목록 저장하기', '서버가 이상할 때 가장 먼저 하는 일은 "지금 뭐가 돌고 있지?" 를 보는 것입니다. 이 실습 환경에는 몇 가지 프로세스가 미리 돌고 있어요. **부모 PID(PPID)까지 포함한 전체 목록**을 `/tmp/ps.txt` 에 저장하세요.', '`ps` 에 `-e`(모든 프로세스)와 `-f`(자세히)를 같이 주면 UID, PID, PPID, 시작 시각, 명령줄까지 나옵니다. 결과는 `>` 로 파일에 보내세요.', 'ps -ef > /tmp/ps.txt
head -n 3 /tmp/ps.txt

# PID 는 프로세스 번호, PPID 는 그 프로세스를 띄운 부모의 번호. 맨 오른쪽 CMD 가 실제 실행한 명령이다', '["sh", "-c", "pkill -x worker.sh; pkill -x batch.sh; pkill -9 -x stubborn.sh; pkill -x hog.sh; pkill -x nc; pkill -f \\"^sleep 60[14]\\"\\nrm -rf /tmp/lab /tmp/*.txt /tmp/*.pid; mkdir -p /tmp/lab\\nprintf ''#!/bin/sh\\\\nwhile true; do sleep 1; done\\\\n'' > /tmp/lab/worker.sh\\ncp /tmp/lab/worker.sh /tmp/lab/batch.sh\\nprintf ''#!/bin/sh\\\\ntrap \\"\\" TERM\\\\nwhile true; do sleep 1; done\\\\n'' > /tmp/lab/stubborn.sh\\nprintf ''#!/bin/sh\\\\nx=$(head -c 40000000 /dev/zero | tr \\"\\\\\\\\0\\" a)\\\\nwhile true; do sleep 1; done\\\\n'' > /tmp/lab/hog.sh\\nchmod +x /tmp/lab/*.sh\\ncd /tmp/lab\\nfor n in worker.sh batch.sh batch.sh batch.sh stubborn.sh hog.sh; do setsid nohup /tmp/lab/$n >/dev/null 2>&1 </dev/null & done\\nsetsid nohup sleep 601 >/dev/null 2>&1 </dev/null &\\nsetsid nohup nc -l -p 8080 >/dev/null 2>&1 </dev/null &\\nsleep 1; true"]', '["sh", "-c", "( head -n 1 /tmp/ps.txt | grep -q \\"^UID\\" && head -n 1 /tmp/ps.txt | grep -q PPID ) && ( grep -q \\"/tmp/lab/worker.sh\\" /tmp/ps.txt ) && ( grep -q \\"sleep 601\\" /tmp/ps.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "제목 줄에 UID 와 PPID 가 있다", "cmd": ["sh", "-c", "head -n 1 /tmp/ps.txt | grep -q \\"^UID\\" && head -n 1 /tmp/ps.txt | grep -q PPID"]}, {"label": "worker.sh 가 목록에 있다", "cmd": ["sh", "-c", "grep -q \\"/tmp/lab/worker.sh\\" /tmp/ps.txt"]}, {"label": "sleep 601 이 목록에 있다", "cmd": ["sh", "-c", "grep -q \\"sleep 601\\" /tmp/ps.txt"]}]', '[{"title": "ps(1) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/ps.1.html"}, {"title": "pgrep·pkill(1) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/pgrep.1.html"}, {"title": "signal(7) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man7/signal.7.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 229 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 229, 2, '이름으로 PID 찾기 (pgrep)', '`worker.sh` 라는 이름의 프로세스가 돌고 있습니다. 목록 전체에서 눈으로 찾는 대신, **이름으로 PID 만** 뽑아 `/tmp/worker.pid` 에 저장하세요. (숫자 한 줄)', '`pgrep 이름` 은 이름이 맞는 프로세스의 PID 만 출력합니다. 이름이 정확히 같은 것만 고르려면 `-x` 를 붙이세요. 번호는 실행할 때마다 달라지므로 직접 읽어서 적지 말고 명령 결과를 파일로 보냅니다.', 'pgrep -x worker.sh > /tmp/worker.pid
cat /tmp/worker.pid

# ps -ef | grep worker 는 grep 자신도 같이 잡힌다. pgrep 은 자기 자신을 빼 주고 PID 만 줘서 스크립트에 쓰기 좋다', '["sh", "-c", "pkill -x worker.sh; pkill -x batch.sh; pkill -9 -x stubborn.sh; pkill -x hog.sh; pkill -x nc; pkill -f \\"^sleep 60[14]\\"\\nrm -rf /tmp/lab /tmp/*.txt /tmp/*.pid; mkdir -p /tmp/lab\\nprintf ''#!/bin/sh\\\\nwhile true; do sleep 1; done\\\\n'' > /tmp/lab/worker.sh\\ncp /tmp/lab/worker.sh /tmp/lab/batch.sh\\nprintf ''#!/bin/sh\\\\ntrap \\"\\" TERM\\\\nwhile true; do sleep 1; done\\\\n'' > /tmp/lab/stubborn.sh\\nprintf ''#!/bin/sh\\\\nx=$(head -c 40000000 /dev/zero | tr \\"\\\\\\\\0\\" a)\\\\nwhile true; do sleep 1; done\\\\n'' > /tmp/lab/hog.sh\\nchmod +x /tmp/lab/*.sh\\ncd /tmp/lab\\nfor n in worker.sh batch.sh batch.sh batch.sh stubborn.sh hog.sh; do setsid nohup /tmp/lab/$n >/dev/null 2>&1 </dev/null & done\\nsetsid nohup sleep 601 >/dev/null 2>&1 </dev/null &\\nsetsid nohup nc -l -p 8080 >/dev/null 2>&1 </dev/null &\\nsleep 1; true"]', '["sh", "-c", "( grep -Eq \\"^[0-9]+$\\" /tmp/worker.pid && [ \\"$(wc -l < /tmp/worker.pid)\\" -eq 1 ] ) && ( [ \\"$(cat /tmp/worker.pid)\\" = \\"$(pgrep -x worker.sh)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "숫자 한 줄이다", "cmd": ["sh", "-c", "grep -Eq \\"^[0-9]+$\\" /tmp/worker.pid && [ \\"$(wc -l < /tmp/worker.pid)\\" -eq 1 ]"]}, {"label": "실제 worker.sh 의 PID 와 같다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/worker.pid)\\" = \\"$(pgrep -x worker.sh)\\" ]"]}]', '[{"title": "ps(1) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/ps.1.html"}, {"title": "pgrep·pkill(1) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/pgrep.1.html"}, {"title": "signal(7) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man7/signal.7.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 229 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 229, 3, 'PID 하나 자세히 보기 (ps -o)', '앞에서 찾은 `worker.sh` 의 **PID, 부모 PID, 실행된 지 얼마나 됐는지(경과 시간), 명령줄** 이 네 가지만 `/tmp/worker_info.txt` 에 저장하세요. (제목 줄 + 데이터 한 줄, 모두 2줄)', '`ps -p PID` 는 그 PID 한 개만 보여 줍니다. 열은 `-o` 뒤에 쉼표로 고릅니다: `pid`, `ppid`, `etime`(경과 시간), `args`(명령줄). PID 자리에는 `$(pgrep ...)` 를 넣을 수 있어요.', 'ps -o pid,ppid,etime,args -p $(pgrep -x worker.sh) > /tmp/worker_info.txt
cat /tmp/worker_info.txt

# -o 로 열을 고르면 필요한 정보만 깔끔히 뽑는다. etime 은 [[dd-]hh:]mm:ss 형식의 경과 시간', '["sh", "-c", "pkill -x worker.sh; pkill -x batch.sh; pkill -9 -x stubborn.sh; pkill -x hog.sh; pkill -x nc; pkill -f \\"^sleep 60[14]\\"\\nrm -rf /tmp/lab /tmp/*.txt /tmp/*.pid; mkdir -p /tmp/lab\\nprintf ''#!/bin/sh\\\\nwhile true; do sleep 1; done\\\\n'' > /tmp/lab/worker.sh\\ncp /tmp/lab/worker.sh /tmp/lab/batch.sh\\nprintf ''#!/bin/sh\\\\ntrap \\"\\" TERM\\\\nwhile true; do sleep 1; done\\\\n'' > /tmp/lab/stubborn.sh\\nprintf ''#!/bin/sh\\\\nx=$(head -c 40000000 /dev/zero | tr \\"\\\\\\\\0\\" a)\\\\nwhile true; do sleep 1; done\\\\n'' > /tmp/lab/hog.sh\\nchmod +x /tmp/lab/*.sh\\ncd /tmp/lab\\nfor n in worker.sh batch.sh batch.sh batch.sh stubborn.sh hog.sh; do setsid nohup /tmp/lab/$n >/dev/null 2>&1 </dev/null & done\\nsetsid nohup sleep 601 >/dev/null 2>&1 </dev/null &\\nsetsid nohup nc -l -p 8080 >/dev/null 2>&1 </dev/null &\\nsleep 1; true"]', '["sh", "-c", "( [ \\"$(wc -l < /tmp/worker_info.txt)\\" -eq 2 ] ) && ( head -n 1 /tmp/worker_info.txt | grep -Eq \\"^ *PID +PPID +ELAPSED +(COMMAND|CMD)\\" ) && ( [ \\"$(sed -n 2p /tmp/worker_info.txt | awk \\"{print \\\\$1}\\")\\" = \\"$(pgrep -x worker.sh)\\" ] ) && ( sed -n 2p /tmp/worker_info.txt | grep -q \\"/tmp/lab/worker.sh\\" )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "두 줄이다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/worker_info.txt)\\" -eq 2 ]"]}, {"label": "제목 줄이 PID PPID ELAPSED 순서다", "cmd": ["sh", "-c", "head -n 1 /tmp/worker_info.txt | grep -Eq \\"^ *PID +PPID +ELAPSED +(COMMAND|CMD)\\""]}, {"label": "데이터 줄 첫 칸이 worker.sh 의 PID 다", "cmd": ["sh", "-c", "[ \\"$(sed -n 2p /tmp/worker_info.txt | awk \\"{print \\\\$1}\\")\\" = \\"$(pgrep -x worker.sh)\\" ]"]}, {"label": "명령줄에 worker.sh 가 있다", "cmd": ["sh", "-c", "sed -n 2p /tmp/worker_info.txt | grep -q \\"/tmp/lab/worker.sh\\""]}]', '[{"title": "ps(1) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/ps.1.html"}, {"title": "pgrep·pkill(1) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/pgrep.1.html"}, {"title": "signal(7) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man7/signal.7.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 229 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 229, 4, '메모리를 가장 많이 쓰는 프로세스', '서버가 느릴 때는 누가 자원을 먹는지 봅니다. 지금 **메모리를 가장 많이 쓰는 프로세스 한 개**를 제목 줄과 함께(2줄) `/tmp/topmem.txt` 에 저장하세요.', '`ps aux` 에 `--sort=-%mem` 을 붙이면 메모리 사용률이 큰 순서로 나옵니다 (`-` 는 큰 것이 위, `+` 나 생략하면 작은 것이 위). 위의 몇 줄만 남기려면 `head -n 2` 를 이어 붙이세요.', 'ps aux --sort=-%mem | head -n 2 > /tmp/topmem.txt
cat /tmp/topmem.txt

# %MEM 은 메모리 사용률, RSS 는 실제로 올라가 있는 메모리(KB). CPU 순으로 보려면 --sort=-%cpu', '["sh", "-c", "pkill -x worker.sh; pkill -x batch.sh; pkill -9 -x stubborn.sh; pkill -x hog.sh; pkill -x nc; pkill -f \\"^sleep 60[14]\\"\\nrm -rf /tmp/lab /tmp/*.txt /tmp/*.pid; mkdir -p /tmp/lab\\nprintf ''#!/bin/sh\\\\nwhile true; do sleep 1; done\\\\n'' > /tmp/lab/worker.sh\\ncp /tmp/lab/worker.sh /tmp/lab/batch.sh\\nprintf ''#!/bin/sh\\\\ntrap \\"\\" TERM\\\\nwhile true; do sleep 1; done\\\\n'' > /tmp/lab/stubborn.sh\\nprintf ''#!/bin/sh\\\\nx=$(head -c 40000000 /dev/zero | tr \\"\\\\\\\\0\\" a)\\\\nwhile true; do sleep 1; done\\\\n'' > /tmp/lab/hog.sh\\nchmod +x /tmp/lab/*.sh\\ncd /tmp/lab\\nfor n in worker.sh batch.sh batch.sh batch.sh stubborn.sh hog.sh; do setsid nohup /tmp/lab/$n >/dev/null 2>&1 </dev/null & done\\nsetsid nohup sleep 601 >/dev/null 2>&1 </dev/null &\\nsetsid nohup nc -l -p 8080 >/dev/null 2>&1 </dev/null &\\nsleep 1; true"]', '["sh", "-c", "( [ \\"$(wc -l < /tmp/topmem.txt)\\" -eq 2 ] ) && ( head -n 1 /tmp/topmem.txt | grep -q PID ) && ( sed -n 2p /tmp/topmem.txt | grep -q \\"/tmp/lab/hog.sh\\" )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "두 줄이다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/topmem.txt)\\" -eq 2 ]"]}, {"label": "제목 줄에 PID 가 있다", "cmd": ["sh", "-c", "head -n 1 /tmp/topmem.txt | grep -q PID"]}, {"label": "1등이 hog.sh 다", "cmd": ["sh", "-c", "sed -n 2p /tmp/topmem.txt | grep -q \\"/tmp/lab/hog.sh\\""]}]', '[{"title": "ps(1) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/ps.1.html"}, {"title": "pgrep·pkill(1) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/pgrep.1.html"}, {"title": "signal(7) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man7/signal.7.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 229 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 229, 5, '8080 포트를 쥔 프로세스 찾기 (ss -ltnp)', '어떤 프로세스가 **8080 번 포트로 연결을 기다리고(LISTEN)** 있습니다. 포트 번호가 들어 있는 줄을 **그 프로세스 정보(이름과 PID)까지 포함해** `/tmp/port8080.txt` 에 저장하세요.', '`ss` 로 소켓을 봅니다. `-l`(LISTEN 상태만), `-t`(TCP), `-n`(포트를 숫자로), `-p`(소켓을 쥔 프로세스)를 합쳐 `-ltnp` 로 쓰고, `grep` 으로 8080 이 있는 줄만 남기세요. (`-p` 는 root 권한이 필요합니다)', 'ss -ltnp | grep 8080 > /tmp/port8080.txt
cat /tmp/port8080.txt

# 맨 오른쪽 users:(("nc",pid=...)) 가 그 포트를 쥔 프로세스. "포트가 이미 사용 중" 오류가 났을 때 제일 먼저 하는 확인이다', '["sh", "-c", "pkill -x worker.sh; pkill -x batch.sh; pkill -9 -x stubborn.sh; pkill -x hog.sh; pkill -x nc; pkill -f \\"^sleep 60[14]\\"\\nrm -rf /tmp/lab /tmp/*.txt /tmp/*.pid; mkdir -p /tmp/lab\\nprintf ''#!/bin/sh\\\\nwhile true; do sleep 1; done\\\\n'' > /tmp/lab/worker.sh\\ncp /tmp/lab/worker.sh /tmp/lab/batch.sh\\nprintf ''#!/bin/sh\\\\ntrap \\"\\" TERM\\\\nwhile true; do sleep 1; done\\\\n'' > /tmp/lab/stubborn.sh\\nprintf ''#!/bin/sh\\\\nx=$(head -c 40000000 /dev/zero | tr \\"\\\\\\\\0\\" a)\\\\nwhile true; do sleep 1; done\\\\n'' > /tmp/lab/hog.sh\\nchmod +x /tmp/lab/*.sh\\ncd /tmp/lab\\nfor n in worker.sh batch.sh batch.sh batch.sh stubborn.sh hog.sh; do setsid nohup /tmp/lab/$n >/dev/null 2>&1 </dev/null & done\\nsetsid nohup sleep 601 >/dev/null 2>&1 </dev/null &\\nsetsid nohup nc -l -p 8080 >/dev/null 2>&1 </dev/null &\\nsleep 1; true"]', '["sh", "-c", "( grep -q LISTEN /tmp/port8080.txt && grep -q \\":8080\\" /tmp/port8080.txt ) && ( grep -q \\"pid=$(pgrep -x nc),\\" /tmp/port8080.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "LISTEN 줄이다", "cmd": ["sh", "-c", "grep -q LISTEN /tmp/port8080.txt && grep -q \\":8080\\" /tmp/port8080.txt"]}, {"label": "그 포트를 쥔 nc 의 PID 가 적혀 있다", "cmd": ["sh", "-c", "grep -q \\"pid=$(pgrep -x nc),\\" /tmp/port8080.txt"]}]', '[{"title": "ps(1) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/ps.1.html"}, {"title": "pgrep·pkill(1) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/pgrep.1.html"}, {"title": "signal(7) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man7/signal.7.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 229 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 229, 6, '방금 띄운 백그라운드 작업의 PID', '터미널에서 `sleep 600 &` 를 실행한 직후에 `echo $!` 를 치면 무엇이 출력될까요?', '`&` 로 띄운 작업이 끝나기를 기다리지 않는 셸이, 방금 일어난 일을 어딘가 기억해 둡니다. `$$`, `$?` 와는 다른 값입니다.', NULL, NULL, '[]', 'choice', '["지금 쓰고 있는 셸 자신의 PID", "방금 백그라운드로 띄운 프로세스(`sleep 600`)의 PID", "직전 명령이 끝났을 때의 종료 코드", "지금 백그라운드에서 돌고 있는 작업의 개수"]', 1, '`$!` 는 **가장 최근에 백그라운드(`&`)로 띄운 프로세스의 PID** 입니다. 그 PID 를 변수나 파일에 적어 두면 나중에 `kill $PID` 로 정확히 그것만 종료할 수 있습니다. 셸 자신의 PID 는 `$$`, 직전 종료 코드는 `$?` 이고, 작업 개수는 `jobs` 로 목록을 봅니다.', NULL, NULL, NULL, '[{"title": "ps(1) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/ps.1.html"}, {"title": "pgrep·pkill(1) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/pgrep.1.html"}, {"title": "signal(7) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man7/signal.7.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 229 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 229, 7, '백그라운드로 띄우고 PID 기록하기', '`sleep 604` 를 **백그라운드로 실행**하고, 그 프로세스의 **PID 를 `/tmp/bg.pid` 에 저장**하세요. 프로세스는 계속 살아 있어야 합니다. (PID 는 직접 적지 말고 셸이 알려 주는 값을 쓰세요)', '명령 끝에 `&` 를 붙이면 백그라운드로 실행됩니다. 바로 다음 명령에서 앞 문제의 `$!` 를 `>` 로 파일에 보내세요. 잘 떴는지는 `jobs` 로 볼 수 있어요.', 'sleep 604 &
echo $! > /tmp/bg.pid
jobs
cat /tmp/bg.pid

# jobs 는 이 터미널에서 띄운 작업 목록. 터미널을 닫아도 살리려면 nohup sleep 604 & 처럼 쓴다', '["sh", "-c", "pkill -x worker.sh; pkill -x batch.sh; pkill -9 -x stubborn.sh; pkill -x hog.sh; pkill -x nc; pkill -f \\"^sleep 60[14]\\"\\nrm -rf /tmp/lab /tmp/*.txt /tmp/*.pid; mkdir -p /tmp/lab\\nprintf ''#!/bin/sh\\\\nwhile true; do sleep 1; done\\\\n'' > /tmp/lab/worker.sh\\ncp /tmp/lab/worker.sh /tmp/lab/batch.sh\\nprintf ''#!/bin/sh\\\\ntrap \\"\\" TERM\\\\nwhile true; do sleep 1; done\\\\n'' > /tmp/lab/stubborn.sh\\nprintf ''#!/bin/sh\\\\nx=$(head -c 40000000 /dev/zero | tr \\"\\\\\\\\0\\" a)\\\\nwhile true; do sleep 1; done\\\\n'' > /tmp/lab/hog.sh\\nchmod +x /tmp/lab/*.sh\\ncd /tmp/lab\\nfor n in worker.sh batch.sh batch.sh batch.sh stubborn.sh hog.sh; do setsid nohup /tmp/lab/$n >/dev/null 2>&1 </dev/null & done\\nsetsid nohup sleep 601 >/dev/null 2>&1 </dev/null &\\nsetsid nohup nc -l -p 8080 >/dev/null 2>&1 </dev/null &\\nsleep 1; true"]', '["sh", "-c", "( grep -Eq \\"^[0-9]+$\\" /tmp/bg.pid ) && ( pgrep -f \\"[s]leep 604\\" > /dev/null ) && ( [ \\"$(cat /tmp/bg.pid)\\" = \\"$(pgrep -f \\"[s]leep 604\\")\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "PID 파일이 숫자 한 줄이다", "cmd": ["sh", "-c", "grep -Eq \\"^[0-9]+$\\" /tmp/bg.pid"]}, {"label": "sleep 604 가 살아 있다", "cmd": ["sh", "-c", "pgrep -f \\"[s]leep 604\\" > /dev/null"]}, {"label": "파일의 PID 가 sleep 604 의 PID 와 같다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/bg.pid)\\" = \\"$(pgrep -f \\"[s]leep 604\\")\\" ]"]}]', '[{"title": "ps(1) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/ps.1.html"}, {"title": "pgrep·pkill(1) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/pgrep.1.html"}, {"title": "signal(7) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man7/signal.7.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 229 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 229, 8, '프로세스 정상 종료하기 (kill)', '`worker.sh` 가 더 이상 필요 없습니다. **이름으로 PID 를 찾아 종료**하세요. 다른 프로세스(`batch.sh`, `sleep 601`)는 그대로 살아 있어야 합니다.', '`kill PID` 는 기본으로 "스스로 정리하고 끝내 달라"는 신호(SIGTERM)를 보냅니다. PID 자리에 앞에서 쓴 `$(pgrep -x worker.sh)` 를 넣으세요. 끝난 뒤 `pgrep` 으로 사라졌는지 확인합니다.', 'kill $(pgrep -x worker.sh)
sleep 1
pgrep -x worker.sh || echo gone

# 번호를 눈으로 옮겨 적다 틀리면 엉뚱한 프로세스를 죽인다. PID 는 pgrep 결과를 그대로 넘기는 게 안전하다', '["sh", "-c", "pkill -x worker.sh; pkill -x batch.sh; pkill -9 -x stubborn.sh; pkill -x hog.sh; pkill -x nc; pkill -f \\"^sleep 60[14]\\"\\nrm -rf /tmp/lab /tmp/*.txt /tmp/*.pid; mkdir -p /tmp/lab\\nprintf ''#!/bin/sh\\\\nwhile true; do sleep 1; done\\\\n'' > /tmp/lab/worker.sh\\ncp /tmp/lab/worker.sh /tmp/lab/batch.sh\\nprintf ''#!/bin/sh\\\\ntrap \\"\\" TERM\\\\nwhile true; do sleep 1; done\\\\n'' > /tmp/lab/stubborn.sh\\nprintf ''#!/bin/sh\\\\nx=$(head -c 40000000 /dev/zero | tr \\"\\\\\\\\0\\" a)\\\\nwhile true; do sleep 1; done\\\\n'' > /tmp/lab/hog.sh\\nchmod +x /tmp/lab/*.sh\\ncd /tmp/lab\\nfor n in worker.sh batch.sh batch.sh batch.sh stubborn.sh hog.sh; do setsid nohup /tmp/lab/$n >/dev/null 2>&1 </dev/null & done\\nsetsid nohup sleep 601 >/dev/null 2>&1 </dev/null &\\nsetsid nohup nc -l -p 8080 >/dev/null 2>&1 </dev/null &\\nsleep 1; true"]', '["sh", "-c", "( ! ps -eo stat=,comm= | grep -Eq \\"^[^Z][^ ]* +worker.sh$\\" ) && ( [ \\"$(pgrep -cx batch.sh)\\" -eq 3 ] ) && ( pgrep -f \\"[s]leep 601\\" > /dev/null )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "worker.sh 가 종료됐다", "cmd": ["sh", "-c", "! ps -eo stat=,comm= | grep -Eq \\"^[^Z][^ ]* +worker.sh$\\""]}, {"label": "batch.sh 3개는 살아 있다", "cmd": ["sh", "-c", "[ \\"$(pgrep -cx batch.sh)\\" -eq 3 ]"]}, {"label": "sleep 601 은 살아 있다", "cmd": ["sh", "-c", "pgrep -f \\"[s]leep 601\\" > /dev/null"]}]', '[{"title": "ps(1) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/ps.1.html"}, {"title": "pgrep·pkill(1) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/pgrep.1.html"}, {"title": "signal(7) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man7/signal.7.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 229 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 229, 9, 'kill 해도 안 죽는 프로세스 (kill -9)', '`stubborn.sh` 가 종료 요청을 무시하며 버티고 있습니다. 먼저 일반 `kill` 로 시도해 보고, 그래도 남아 있으면 **끝까지 종료**시키세요. 다른 프로세스는 건드리지 않습니다.', '일반 `kill` 뒤에 `pgrep -a stubborn.sh` 로 아직 있는지 보세요. 무시할 수 없는 가장 강한 신호의 번호는 `kill -l` 로 신호 목록을 보면 찾을 수 있습니다. 이 신호는 프로세스가 정리할 기회를 주지 않으니 마지막 수단입니다.', 'kill $(pgrep -x stubborn.sh)
sleep 1
pgrep -a stubborn.sh      # 아직 남아 있음
kill -9 $(pgrep -x stubborn.sh)
sleep 1
pgrep -a stubborn.sh || echo gone

# SIGTERM(15)은 프로세스가 무시할 수 있지만 SIGKILL(9)은 커널이 직접 끝내서 막을 수 없다. 대신 임시 파일·잠금 정리가 안 되므로 TERM 먼저, 9 는 나중', '["sh", "-c", "pkill -x worker.sh; pkill -x batch.sh; pkill -9 -x stubborn.sh; pkill -x hog.sh; pkill -x nc; pkill -f \\"^sleep 60[14]\\"\\nrm -rf /tmp/lab /tmp/*.txt /tmp/*.pid; mkdir -p /tmp/lab\\nprintf ''#!/bin/sh\\\\nwhile true; do sleep 1; done\\\\n'' > /tmp/lab/worker.sh\\ncp /tmp/lab/worker.sh /tmp/lab/batch.sh\\nprintf ''#!/bin/sh\\\\ntrap \\"\\" TERM\\\\nwhile true; do sleep 1; done\\\\n'' > /tmp/lab/stubborn.sh\\nprintf ''#!/bin/sh\\\\nx=$(head -c 40000000 /dev/zero | tr \\"\\\\\\\\0\\" a)\\\\nwhile true; do sleep 1; done\\\\n'' > /tmp/lab/hog.sh\\nchmod +x /tmp/lab/*.sh\\ncd /tmp/lab\\nfor n in worker.sh batch.sh batch.sh batch.sh stubborn.sh hog.sh; do setsid nohup /tmp/lab/$n >/dev/null 2>&1 </dev/null & done\\nsetsid nohup sleep 601 >/dev/null 2>&1 </dev/null &\\nsetsid nohup nc -l -p 8080 >/dev/null 2>&1 </dev/null &\\nsleep 1; true"]', '["sh", "-c", "( ! ps -eo stat=,comm= | grep -Eq \\"^[^Z][^ ]* +stubborn.sh$\\" ) && ( ps -eo stat=,comm= | grep -Eq \\"^[^Z][^ ]* +worker.sh$\\" ) && ( pgrep -f \\"[s]leep 601\\" > /dev/null )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "stubborn.sh 가 종료됐다", "cmd": ["sh", "-c", "! ps -eo stat=,comm= | grep -Eq \\"^[^Z][^ ]* +stubborn.sh$\\""]}, {"label": "worker.sh 는 살아 있다", "cmd": ["sh", "-c", "ps -eo stat=,comm= | grep -Eq \\"^[^Z][^ ]* +worker.sh$\\""]}, {"label": "sleep 601 은 살아 있다", "cmd": ["sh", "-c", "pgrep -f \\"[s]leep 601\\" > /dev/null"]}]', '[{"title": "ps(1) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/ps.1.html"}, {"title": "pgrep·pkill(1) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/pgrep.1.html"}, {"title": "signal(7) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man7/signal.7.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 229 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 229, 10, '강제 종료 신호 번호', '종료 요청을 무시하는 `stubborn.sh` 를 확실히 끝내려고 합니다. **무시할 수 없는 강제 종료 신호**(SIGKILL)의 번호를 빈칸에 채우세요.', '신호 목록은 `kill -l` 로 볼 수 있습니다. 기본 신호(SIGTERM, 15)는 프로세스가 무시할 수 있어서 이 상황에는 맞지 않아요. 0 은 신호를 실제로 보내지 않고 살아 있는지만 확인합니다.', NULL, NULL, '[]', 'fill', '["9", "15", "0", "18"]', NULL, '`kill -9`(SIGKILL)은 프로세스에 전달되지 않고 커널이 바로 끝내므로 무시할 수 없습니다. 15(SIGTERM)는 기본 신호로 프로세스가 정리하고 끝낼 기회를 주지만 무시당할 수 있고, 0 은 신호를 보내지 않고 PID 존재만 확인하며, 18(SIGCONT)은 멈춘 프로세스를 다시 실행시킵니다.', '[0]', 'kill -{0} $(pgrep -x stubborn.sh)', NULL, '[{"title": "ps(1) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/ps.1.html"}, {"title": "pgrep·pkill(1) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/pgrep.1.html"}, {"title": "signal(7) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man7/signal.7.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 229 AND order_index = 10);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 229, 11, '이름이 같은 프로세스 한꺼번에 종료 (pkill)', '`batch.sh` 가 **세 개** 떠 있습니다. PID 를 하나씩 적지 말고 **이름으로 한 번에** 모두 종료하세요. `worker.sh`, `stubborn.sh`, `sleep 601` 은 건드리면 안 됩니다.', '`pgrep -a batch.sh` 로 대상이 어떤 프로세스인지 먼저 확인하세요. `pkill` 은 `pgrep` 과 같은 방식으로 이름을 골라 신호를 보냅니다. 이름이 정확히 같은 것만 고르는 `-x` 를 잊지 마세요.', 'pgrep -a batch.sh
pkill -x batch.sh
sleep 1
pgrep -c -x batch.sh

# pkill batch 처럼 -x 없이 쓰면 이름에 batch 가 들어간 다른 프로세스까지 죽일 수 있다. 먼저 pgrep 으로 대상을 확인하는 습관', '["sh", "-c", "pkill -x worker.sh; pkill -x batch.sh; pkill -9 -x stubborn.sh; pkill -x hog.sh; pkill -x nc; pkill -f \\"^sleep 60[14]\\"\\nrm -rf /tmp/lab /tmp/*.txt /tmp/*.pid; mkdir -p /tmp/lab\\nprintf ''#!/bin/sh\\\\nwhile true; do sleep 1; done\\\\n'' > /tmp/lab/worker.sh\\ncp /tmp/lab/worker.sh /tmp/lab/batch.sh\\nprintf ''#!/bin/sh\\\\ntrap \\"\\" TERM\\\\nwhile true; do sleep 1; done\\\\n'' > /tmp/lab/stubborn.sh\\nprintf ''#!/bin/sh\\\\nx=$(head -c 40000000 /dev/zero | tr \\"\\\\\\\\0\\" a)\\\\nwhile true; do sleep 1; done\\\\n'' > /tmp/lab/hog.sh\\nchmod +x /tmp/lab/*.sh\\ncd /tmp/lab\\nfor n in worker.sh batch.sh batch.sh batch.sh stubborn.sh hog.sh; do setsid nohup /tmp/lab/$n >/dev/null 2>&1 </dev/null & done\\nsetsid nohup sleep 601 >/dev/null 2>&1 </dev/null &\\nsetsid nohup nc -l -p 8080 >/dev/null 2>&1 </dev/null &\\nsleep 1; true"]', '["sh", "-c", "( ! ps -eo stat=,comm= | grep -Eq \\"^[^Z][^ ]* +batch.sh$\\" ) && ( ps -eo stat=,comm= | grep -Eq \\"^[^Z][^ ]* +worker.sh$\\" ) && ( ps -eo stat=,comm= | grep -Eq \\"^[^Z][^ ]* +stubborn.sh$\\" ) && ( pgrep -f \\"[s]leep 601\\" > /dev/null )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "batch.sh 가 모두 종료됐다", "cmd": ["sh", "-c", "! ps -eo stat=,comm= | grep -Eq \\"^[^Z][^ ]* +batch.sh$\\""]}, {"label": "worker.sh 는 살아 있다", "cmd": ["sh", "-c", "ps -eo stat=,comm= | grep -Eq \\"^[^Z][^ ]* +worker.sh$\\""]}, {"label": "stubborn.sh 는 살아 있다", "cmd": ["sh", "-c", "ps -eo stat=,comm= | grep -Eq \\"^[^Z][^ ]* +stubborn.sh$\\""]}, {"label": "sleep 601 은 살아 있다", "cmd": ["sh", "-c", "pgrep -f \\"[s]leep 601\\" > /dev/null"]}]', '[{"title": "ps(1) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/ps.1.html"}, {"title": "pgrep·pkill(1) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/pgrep.1.html"}, {"title": "signal(7) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man7/signal.7.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 229 AND order_index = 11);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 229, 12, '프로세스를 안전하게 종료하는 순서', '`stubborn.sh` 같은 프로세스를 종료해야 합니다. 안전한 순서대로 놓으세요. **앞에서 뒤**로 놓습니다.', '대상을 확인하고 → 정중하게 요청하고 → 결과를 보고 → 안 되면 강하게 → 마지막으로 확인합니다.', NULL, NULL, '[]', 'order', '["`pgrep -a stubborn.sh` 로 PID 와 명령줄을 확인해 대상이 맞는지 본다", "`kill PID` 로 기본 신호(SIGTERM)를 보내 정상 종료를 요청한다", "잠시 기다린 뒤 `pgrep` 이나 `ps -p PID` 로 사라졌는지 확인한다", "남아 있으면 `kill -9 PID` 로 강제 종료한다", "`pgrep` 으로 정말 없어졌는지 다시 확인한다"]', NULL, '**대상 확인 → `kill`(TERM) → 사라졌는지 확인 → 남았으면 `kill -9` → 최종 확인** 입니다. 처음부터 `kill -9` 를 쓰면 프로세스가 임시 파일·잠금·연결을 정리할 기회를 잃고, PID 를 확인하지 않고 보내면 엉뚱한 프로세스를 죽일 수 있습니다.', '[0, 1, 2, 3, 4]', NULL, NULL, '[{"title": "ps(1) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/ps.1.html"}, {"title": "pgrep·pkill(1) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man1/pgrep.1.html"}, {"title": "signal(7) 리눅스 매뉴얼", "url": "https://man7.org/linux/man-pages/man7/signal.7.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 229 AND order_index = 12);

UPDATE quest_set SET display_order = 172, unit_id = (SELECT id FROM unit WHERE id = 4), icon = '🔪' WHERE id = 229;
